package main

import "fmt"

func mutate(s []int) { s[0] = 9 } // shared array
func grow(s []int)   { s = append(s, 100); _ = s } // local header only

func main() {
	a := []int{1, 2, 3}
	mutate(a)
	grow(a)
	fmt.Println(a) // element changed; length did not
	// Output: [9 2 3]
}

package main

import "fmt"

func main() {
	a := []int{1, 2, 3, 4}
	b := a[1:3]  // header over a's array
	b[0] = 99    // writes into the shared array
	fmt.Println(a) // a[1] changed
	// Output: [1 99 3 4]
}

package main

import "fmt"

func main() {
	a := []int{1, 2, 3, 4}
	b := a[:2]           // len 2, cap 4 (spare capacity)
	b = append(b, 100)   // fits in cap -> writes into a[2]
	fmt.Println(a)       // aliasing visible
	fmt.Println(b)
	// Output:
	// [1 2 100 4]
	// [1 2 100]
}

package main

import "fmt"

func main() {
	a := []int{1, 2, 3, 4}
	b := a[0:2:2]      // cap capped at 2, no spare room
	b = append(b, 100) // cap exhausted -> reallocates a new array
	fmt.Println(a)     // untouched
	// Output: [1 2 3 4]
}

package main

import "fmt"

func main() {
	src := []int{1, 2, 3}
	dst := make([]int, len(src)) // fresh backing array
	n := copy(dst, src)          // returns number copied
	dst[0] = 99                  // does NOT affect src
	fmt.Println(n, src, dst)
	// Output: 3 [1 2 3] [99 2 3]
}

package main

import "fmt"

// Copy the window out so the big backing array can be freed.
func firstTen(big []byte) []byte {
	out := make([]byte, 10)
	copy(out, big[:10]) // independent of big
	return out
}

func main() {
	big := make([]byte, 1<<20)
	big[0] = 42
	small := firstTen(big)
	fmt.Println(len(small), small[0])
	// Output: 10 42
}

