package solution

func Remove(s []int, i int) []int {
	// Shift the tail left over index i, then trim the length by one.
	copy(s[i:], s[i+1:]) // move s[i+1:] down into s[i:]
	return s[:len(s)-1]  // drop the now-duplicated last element
}

