package solution

import (
	"reflect"
	"testing"
)

func TestRemove(t *testing.T) {
	cases := []struct {
		in   []int
		i    int
		want []int
	}{
		{[]int{1, 2, 3, 4}, 1, []int{1, 3, 4}},
		{[]int{1, 2, 3}, 0, []int{2, 3}},
		{[]int{1, 2, 3}, 2, []int{1, 2}},
		{[]int{5}, 0, []int{}},
	}
	for _, c := range cases {
		cp := append([]int(nil), c.in...) // copy so cases stay independent
		if got := Remove(cp, c.i); !reflect.DeepEqual(got, c.want) {
			t.Errorf("Remove(%v, %d)=%v want %v", c.in, c.i, got, c.want)
		}
	}
}

