func Chunk[T any](s []T, size int) [][]T {
	if size <= 0 {
		return nil // no valid chunk size
	}
	n := len(s)
	chunks := make([][]T, 0, (n+size-1)/size) // pre-size: ceil(n/size)
	for i := 0; i < n; i += size {
		end := i + size
		if end > n {
			end = n // clamp the last (short) chunk
		}
		chunks = append(chunks, s[i:end]) // sub-slice window, at most `size`
	}
	return chunks
}

func Clone(s []int) []int {
	if s == nil {
		return nil // preserve nil-ness
	}
	out := make([]int, len(s)) // fresh backing array
	copy(out, s)               // copy elements, not the header
	return out
}
